lastmod:
 = the page's last git commit date
    (git-revision-date-localized plugin) instead of the build date on every page. -#}

{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% set changed = file.page.meta.git_revision_date_localized_raw_iso_date if file.page.meta else None %}
         {% if changed %}{{ changed }}{% elif file.page.update_date %}{{ file.page.update_date }}{% endif %}

    {%- endif -%}
{% endfor %}
